FROM `dbc_spellname` n LEFT JOIN `dbc_spell` sp ON sp.`ID` = n.`ID` LEFT JOIN `dbc_spellmisc` m ON m.`SpellID` = n.`ID` AND m.`DifficultyID` = 0 LEFT JOIN `dbc_spellcategories` c ON c.`SpellID` = n.`ID` AND c.`DifficultyID` = 0 LEFT JOIN `dbc_spellclassoptions` co ON co.`SpellID` = n.`ID` LEFT JOIN `dbc_spellcooldowns` cd ON cd.`SpellID` = n.`ID` AND cd.`DifficultyID` = 0 LEFT JOIN `dbc_spellinterrupts` ir ON ir.`SpellID` = n.`ID` AND ir.`DifficultyID` = 0 LEFT JOIN `dbc_spelllevels` lv ON lv.`SpellID` = n.`ID` AND lv.`DifficultyID` = 0 LEFT JOIN `dbc_spellauraoptions` ao ON ao.`SpellID` = n.`ID` AND ao.`DifficultyID` = 0 LEFT JOIN `dbc_spellaurarestrictions` ar ON ar.`SpellID` = n.`ID` AND ar.`DifficultyID` = 0 LEFT JOIN `dbc_spellcastingrequirements` cr ON cr.`SpellID` = n.`ID` LEFT JOIN `dbc_spellequippeditems` ei ON ei.`SpellID` = n.`ID` LEFT JOIN `dbc_spellpower` pw ON pw.`SpellID` = n.`ID` AND pw.`OrderIndex` = 0 LEFT JOIN `dbc_spellreagents` rg ON rg.`SpellID` = n.`ID` LEFT JOIN `dbc_spellshapeshift` sh ON sh.`SpellID` = n.`ID` LEFT JOIN `dbc_spelltargetrestrictions` tr ON tr.`SpellID` = n.`ID` AND tr.`DifficultyID` = 0 LEFT JOIN `dbc_spelltotems` tt ON tt.`SpellID` = n.`ID` LEFT JOIN `dbc_spelleffect` f0 ON f0.`SpellID` = n.`ID` AND f0.`DifficultyID` = 0 AND f0.`EffectIndex` = 0 LEFT JOIN `dbc_spelleffect` f1 ON f1.`SpellID` = n.`ID` AND f1.`DifficultyID` = 0 AND f1.`EffectIndex` = 1 LEFT JOIN `dbc_spelleffect` f2 ON f2.`SpellID` = n.`ID` AND f2.`DifficultyID` = 0 AND f2.`EffectIndex` = 2 LEFT JOIN `spell_extra` x ON x.`spell_id` = n.`ID`
